const fs = require("fs");
const pdfParse = require("pdf-parse");
const ExcelJS = require("exceljs");

async function extractFirstPageToExcel(pdfPath, excelPath) {
  // Read the PDF
  const pdfBuffer = fs.readFileSync(pdfPath);

  // Parse only the first page (pagerender callback filters by page number)
  const options = {
    max: 1, // extract only the first page
  };
  const data = await pdfParse(pdfBuffer, options);

  console.log(`PDF Title : ${data.info?.Title || "(none)"}`);
  console.log(`Total pages: ${data.numpages}`);
  console.log(`Extracted ${data.text.length} characters from page 1.\n`);

  // Build the Excel workbook
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet("Page 1 Text");

  // Header row
  sheet.columns = [
    { header: "Line #", key: "line", width: 10 },
    { header: "Text", key: "text", width: 100 },
  ];
  sheet.getRow(1).font = { bold: true };

  // Split extracted text into lines and add each as a row
  const lines = data.text.split("\n");
  lines.forEach((line, i) => {
    sheet.addRow({ line: i + 1, text: line });
  });

  // Save
  await workbook.xlsx.writeFile(excelPath);
  console.log(`✅ Saved ${lines.length} lines to ${excelPath}`);
}

// --- Run ---
const pdfPath = process.argv[2] || "testbed/docs/handbook.pdf";
const excelPath = process.argv[3] || "page1_text.xlsx";

extractFirstPageToExcel(pdfPath, excelPath).catch((err) => {
  console.error("Error:", err.message);
  process.exit(1);
});

