const fs = require("fs");
const pdfjsLib = require("pdfjs-dist/legacy/build/pdf.js");
const ExcelJS = require("exceljs");

async function extractFirstPageToExcel(pdfPath, excelPath) {
  // Load the PDF document
  const data = new Uint8Array(fs.readFileSync(pdfPath));
  const doc = await pdfjsLib.getDocument({ data }).promise;

  console.log(`PDF loaded: ${doc.numPages} page(s)`);

  // Get only the first page
  const page = await doc.getPage(1);
  const content = await page.getTextContent();

  // Combine text items into a single string, then split into lines
  const fullText = content.items.map((item) => item.str).join("");
  const lines = fullText.split("\n").filter((l) => l.trim().length > 0);

  console.log(`Extracted ${lines.length} non-empty lines from page 1.\n`);

  // Build the Excel workbook
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet("Page 1 Text");

  sheet.columns = [
    { header: "Line #", key: "line", width: 10 },
    { header: "Text", key: "text", width: 120 },
  ];
  sheet.getRow(1).font = { bold: true };

  lines.forEach((text, i) => {
    sheet.addRow({ line: i + 1, text });
  });

  await workbook.xlsx.writeFile(excelPath);
  console.log(`✅ Saved to ${excelPath}`);
}

